                        }

                        for _, row := range infoRows {
                                if !slices.Contains(s.expectColumns, row.Name) {
                                        t.Fatalf("Missing %q column in %v", row.Name, s.expectColumns)
                                }
                        }
                })
        }

        ensureNoTempViews(app, t)
}

