                // measure to discourage multiple inline sql statements execution
                viewQuery := fmt.Sprintf("CREATE VIEW {{%s}} AS SELECT * FROM (%s)", name, selectQuery)
                if _, err := txApp.DB().NewQuery(viewQuery).Execute(); err != nil {
                        return err
